// Christmas carols synthesised in real time with WebAudio.
// The compositions used are in the public domain (Jingle Bells – J. L. Pierpont 1857,
// Silent Night – F. X. Gruber 1818, We Wish You a Merry Christmas – trad.), and this
// performance is generated by code, so no third-party recording/licence is involved.
// If a licensed /audio/k-carol.mp3 is deployed, it is used instead (see docs).

const N = (name) => {
  const m = /^([A-G])(#|b)?(\d)$/.exec(name);
  const base = { C: 0, D: 2, E: 4, F: 5, G: 7, A: 9, B: 11 }[m[1]] + (m[2] === '#' ? 1 : m[2] === 'b' ? -1 : 0);
  return 12 * (+m[3] + 1) + base;
};
const seq = (s) => s.trim().split(/\s+/).map((tok) => { const [n, d] = tok.split(':'); return [n === 'r' ? null : N(n), +d]; });

export const SONGS = [
  {
    title: 'Jingle Bells', bpm: 168, chords: ['C', 'C', 'C', 'C', 'F', 'C', 'G', 'G', 'C', 'C', 'C', 'C', 'F', 'C', 'G', 'C'], beatsPerBar: 4, bells: true,
    notes: seq(`E4:1 E4:1 E4:2 E4:1 E4:1 E4:2 E4:1 G4:1 C4:1.5 D4:0.5 E4:4 F4:1 F4:1 F4:1.5 F4:0.5 F4:1 E4:1 E4:1 E4:0.5 E4:0.5 E4:1 D4:1 D4:1 E4:1 D4:2 G4:2
      E4:1 E4:1 E4:2 E4:1 E4:1 E4:2 E4:1 G4:1 C4:1.5 D4:0.5 E4:4 F4:1 F4:1 F4:1.5 F4:0.5 F4:1 E4:1 E4:1 E4:0.5 E4:0.5 G4:1 G4:1 F4:1 D4:1 C4:4`),
  },
  {
    title: 'Silent Night', bpm: 84, chords: ['C', 'C', 'C', 'C', 'G', 'G', 'C', 'C', 'F', 'F', 'C', 'C', 'F', 'F', 'C', 'C', 'G', 'G', 'C', 'C', 'C', 'G', 'C', 'C'], beatsPerBar: 3,
    notes: seq(`G4:1.5 A4:0.5 G4:1 E4:3 G4:1.5 A4:0.5 G4:1 E4:3 D5:2 D5:1 B4:3 C5:2 C5:1 G4:3
      A4:2 A4:1 C5:1.5 B4:0.5 A4:1 G4:1.5 A4:0.5 G4:1 E4:3 A4:2 A4:1 C5:1.5 B4:0.5 A4:1 G4:1.5 A4:0.5 G4:1 E4:3
      D5:2 D5:1 F5:1.5 D5:0.5 B4:1 C5:3 E5:3 C5:1 G4:1 E4:1 G4:1.5 F4:0.5 D4:1 C4:6`),
  },
  {
    title: 'We Wish You a Merry Christmas', bpm: 150, chords: ['C', 'F', 'D', 'G', 'E', 'A', 'F', 'G', 'C', 'C'], beatsPerBar: 3, bells: true,
    notes: seq(`G4:1 C5:1 C5:0.5 D5:0.5 C5:0.5 B4:0.5 A4:1 A4:1 A4:1 D5:1 D5:0.5 E5:0.5 D5:0.5 C5:0.5 B4:1 G4:1 G4:1 E5:1 E5:0.5 F5:0.5 E5:0.5 D5:0.5 C5:1 A4:1 G4:0.5 G4:0.5 A4:1 D5:1 B4:1 C5:3`),
  },
];

const CHORD = { C: [48, 55, 64], F: [53, 57, 60], G: [43, 55, 59], D: [50, 54, 57], E: [52, 56, 59], A: [45, 52, 57] };
const hz = (m) => 440 * Math.pow(2, (m - 69) / 12);

export class CarolPlayer {
  constructor() {
    this.ctx = null;
    this.playing = false;
    this.volume = +(localStorage.getItem('cw.carolVol') ?? 0.55);
    this.ambientVolume = +(localStorage.getItem('cw.ambVol') ?? 0.35);
    this.songIndex = 0;
    this.duck = 1;
    this.mp3 = null;
  }

  init() {
    if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume(); return; }
    this.ctx = new (window.AudioContext || window.webkitAudioContext)();
    this.music = this.ctx.createGain();
    this.music.gain.value = this.volume;
    this.duckGain = this.ctx.createGain();
    this.music.connect(this.duckGain);
    // light reverb via feedback delay
    const delay = this.ctx.createDelay(); delay.delayTime.value = 0.23;
    const fb = this.ctx.createGain(); fb.gain.value = 0.28;
    const wet = this.ctx.createGain(); wet.gain.value = 0.3;
    this.music.connect(delay); delay.connect(fb); fb.connect(delay); delay.connect(wet); wet.connect(this.duckGain);
    this.duckGain.connect(this.ctx.destination);
    this.ambient = this.ctx.createGain();
    this.ambient.gain.value = 0;
    this.ambient.connect(this.ctx.destination);
    this.startWind();
    // optional licensed recording
    fetch('/audio/k-carol.mp3', { method: 'HEAD' }).then((r) => {
      if (r.ok && (r.headers.get('content-type') || '').includes('audio')) {
        this.mp3 = new Audio('/audio/k-carol.mp3');
        this.mp3.loop = true;
        this.ctx.createMediaElementSource(this.mp3).connect(this.music);
      }
    }).catch(() => {});
  }

  startWind() {
    const ctx = this.ctx;
    const len = ctx.sampleRate * 4;
    const buf = ctx.createBuffer(1, len, ctx.sampleRate);
    const d = buf.getChannelData(0);
    let last = 0;
    for (let i = 0; i < len; i++) { last = (last + 0.02 * (Math.random() * 2 - 1)) / 1.02; d[i] = last * 3.5; }
    const src = ctx.createBufferSource(); src.buffer = buf; src.loop = true;
    const bp = ctx.createBiquadFilter(); bp.type = 'bandpass'; bp.frequency.value = 500; bp.Q.value = 0.6;
    const lfo = ctx.createOscillator(); lfo.frequency.value = 0.09;
    const lfoGain = ctx.createGain(); lfoGain.gain.value = 260;
    lfo.connect(lfoGain); lfoGain.connect(bp.frequency);
    src.connect(bp); bp.connect(this.ambient);
    src.start(); lfo.start();
  }

  setAmbient(on) {
    this.init();
    this.ambientOn = on;
    this.ambient.gain.setTargetAtTime(on ? this.ambientVolume : 0, this.ctx.currentTime, 0.5);
  }

  setAmbientVolume(v) {
    this.ambientVolume = v;
    localStorage.setItem('cw.ambVol', v);
    if (this.ambient && this.ambientOn) this.ambient.gain.setTargetAtTime(v, this.ctx.currentTime, 0.2);
  }

  setVolume(v) {
    this.volume = v;
    localStorage.setItem('cw.carolVol', v);
    if (this.music) this.music.gain.setTargetAtTime(v, this.ctx.currentTime, 0.1);
  }

  // Voice ducking: lower music while someone (or I) is talking.
  setDuck(active) {
    const target = active ? 0.25 : 1;
    if (target === this.duck || !this.duckGain) return;
    this.duck = target;
    this.duckGain.gain.setTargetAtTime(target, this.ctx.currentTime, active ? 0.08 : 0.6);
  }

  play() {
    this.init();
    if (this.playing) return;
    this.playing = true;
    localStorage.setItem('cw.carolOn', '1');
    if (this.mp3) { this.mp3.play().catch(() => {}); return; }
    this.nextTime = this.ctx.currentTime + 0.1;
    this.noteIdx = 0;
    this.beat = 0;
    this.timer = setInterval(() => this.schedule(), 100);
  }

  pause() {
    this.playing = false;
    localStorage.setItem('cw.carolOn', '0');
    clearInterval(this.timer);
    this.mp3?.pause();
  }

  next() { this.songIndex = (this.songIndex + 1) % SONGS.length; this.noteIdx = 0; this.beat = 0; }

  get title() { return this.mp3 ? 'K-Carol' : SONGS[this.songIndex].title; }

  schedule() {
    const song = SONGS[this.songIndex];
    const spb = 60 / song.bpm;
    while (this.nextTime < this.ctx.currentTime + 0.4) {
      if (this.noteIdx >= song.notes.length) {
        this.nextTime += spb * 4;
        this.next();
        this.onSong?.(this.title);
        return;
      }
      const [m, d] = song.notes[this.noteIdx++];
      const t = this.nextTime;
      // chords on bar starts
      if (Math.abs(this.beat % song.beatsPerBar) < 1e-6) {
        const bar = Math.floor(this.beat / song.beatsPerBar);
        const ch = CHORD[song.chords[bar % song.chords.length]];
        for (const cm of ch) this.pad(hz(cm), t, spb * song.beatsPerBar);
        if (song.bells) this.sleigh(t, spb, song.beatsPerBar);
      }
      if (m !== null) this.bell(hz(m), t, Math.min(d * spb, 1.8));
      this.nextTime += d * spb;
      this.beat += d;
    }
  }

  bell(f, t, dur) {
    const ctx = this.ctx;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0, t);
    g.gain.linearRampToValueAtTime(0.22, t + 0.008);
    g.gain.exponentialRampToValueAtTime(0.001, t + dur + 0.6);
    g.connect(this.music);
    for (const [mul, amp] of [[1, 1], [2, 0.35], [3.01, 0.12], [4.2, 0.05]]) {
      const o = ctx.createOscillator(); o.type = 'sine'; o.frequency.value = f * mul;
      const og = ctx.createGain(); og.gain.value = amp;
      o.connect(og); og.connect(g);
      o.start(t); o.stop(t + dur + 0.7);
    }
  }

  pad(f, t, dur) {
    const ctx = this.ctx;
    const o = ctx.createOscillator(); o.type = 'triangle'; o.frequency.value = f;
    const lp = ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 900;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime(0.035, t + 0.15); g.gain.linearRampToValueAtTime(0, t + dur);
    o.connect(lp); lp.connect(g); g.connect(this.music);
    o.start(t); o.stop(t + dur + 0.05);
  }

  sleigh(t, spb, beats) {
    const ctx = this.ctx;
    if (!this.noiseBuf) {
      this.noiseBuf = ctx.createBuffer(1, ctx.sampleRate * 0.2, ctx.sampleRate);
      const d = this.noiseBuf.getChannelData(0);
      for (let i = 0; i < d.length; i++) d[i] = (Math.random() * 2 - 1) * Math.exp(-i / (ctx.sampleRate * 0.04));
    }
    for (let b = 0; b < beats; b++) {
      const s = ctx.createBufferSource(); s.buffer = this.noiseBuf;
      const hp = ctx.createBiquadFilter(); hp.type = 'highpass'; hp.frequency.value = 6000;
      const g = ctx.createGain(); g.gain.value = 0.05;
      s.connect(hp); hp.connect(g); g.connect(this.music);
      s.start(t + b * spb);
    }
  }
}
